ALTER TABLE plans ADD COLUMN estimated_duration TEXT;
ALTER TABLE plans ADD COLUMN phases TEXT DEFAULT '[]';

UPDATE plans
SET
  estimated_duration = '10–12 days',
  phases = '[{"id":"phase-1","title":"Phase 1: Preparation & Conditioning","description":"Permits, gear acquisition, and high-altitude training","target_date":"2027-08-15","tasks":[{"id":"task-1-1","title":"Obtain ACAP & TIMS permits in Pokhara","description":"Submit paperwork and passport photos at the Nepal Tourism Board in Damside, Pokhara","completed":true},{"id":"task-1-2","title":"Gear check: thermal layers, microspikes & trekking poles","description":"Inspect cold-weather layers and break in waterproof trekking boots on practice trails","completed":true}]},{"id":"phase-2","title":"Phase 2: Travel & Foothill Trekking","description":"Journey from Pokhara to the Modi Khola trailhead and climb to Chhomrong","target_date":"2027-10-08","tasks":[{"id":"task-2-1","title":"Fly to Kathmandu and scenic drive to Pokhara","description":"Arrive in Kathmandu (KTM) and take coach or flight to lakeside Pokhara","completed":false},{"id":"task-2-2","title":"Trek Days 1–3: Nayapul to Ghandruk and Chhomrong","description":"Ascend stone staircases through Gurung villages with views of Annapurna South","completed":false}]},{"id":"phase-3","title":"Phase 3: Deep Sanctuary & Summit","description":"Enter the alpine gorge beneath Machapuchare and reach the ABC amphitheater","target_date":"2027-10-14","tasks":[{"id":"task-3-1","title":"Trek Days 4–6: Bamboo through Deurali to MBC (3,700m)","description":"Hike along Modi Khola gorge, acclimatizing steadily into sub-alpine terrain","completed":false},{"id":"task-3-2","title":"Trek Day 7: Sunrise hike to Annapurna Base Camp (4,130m)","description":"Pre-dawn 2-hour gentle ascent into the 360-degree mountain amphitheater of Annapurna I, Annapurna South, and Hiunchuli","completed":false}]},{"id":"phase-4","title":"Phase 4: Descent & Hot Springs Recovery","description":"Retrace the trail down the valley and soak in natural thermal waters","target_date":"2027-10-17","tasks":[{"id":"task-4-1","title":"Descend via Bamboo to Jhinu Danda natural hot springs","description":"Long descent down the valley, soothing tired muscles in natural riverside thermal pools","completed":false}]}]'
WHERE title = 'Annapurna Base Camp Trek';
